-- ----------------------------
-- Table structure for course_objective
-- ----------------------------
DROP TABLE IF EXISTS `course_objective`;
CREATE TABLE `course_objective`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `outline_id` bigint(0) NOT NULL COMMENT '所属大纲',
  `obj_no` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标编号, 如 1-1',
  `dimension` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '维度 (知识/能力/价值)',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '目标描述',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_outline`(`outline_id`) USING BTREE,
  CONSTRAINT `fk_obj_outline` FOREIGN KEY (`outline_id`) REFERENCES `course_outline` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 62 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '课程目标' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of course_objective
-- ----------------------------
INSERT INTO `course_objective` VALUES (1, 1, '1-1', '知识', '掌握线性表、栈、队列、树、图等基本数据结构的逻辑结构和物理存储实现，理解各类数据结构的特点和适用场景');
INSERT INTO `course_objective` VALUES (2, 1, '2-1', '能力', '能够根据实际应用场景选择合适的数据结构，综合运用所学知识设计高效算法解决复杂工程问题');
INSERT INTO `course_objective` VALUES (3, 1, '2-2', '能力', '掌握算法时间复杂度与空间复杂度的分析方法，能够评估和比较不同算法的效率并做出合理选择');
INSERT INTO `course_objective` VALUES (4, 1, '3-1', '价值', '培养严谨的程序设计习惯、计算思维能力和团队协作精神，树立软件工程职业道德意识');
INSERT INTO `course_objective` VALUES (5, 2, '2-1', '能力', '掌握C语言基本语法、数据类型、运算符与表达式、控制结构及函数的定义与调用方法');
INSERT INTO `course_objective` VALUES (6, 2, '2-2', '能力', '能够运用结构化程序设计方法，综合使用数组、指针和结构体等工具解决实际编程问题');
INSERT INTO `course_objective` VALUES (7, 2, '2-3', '能力', '掌握文件操作和模块化程序设计技术，具备独立开发中小规模应用程序的能力');
INSERT INTO `course_objective` VALUES (8, 3, '1-1', '知识', '理解计算机网络体系结构、OSI和TCP/IP参考模型，掌握物理层、数据链路层、网络层、传输层及应用层的核心协议原理');
INSERT INTO `course_objective` VALUES (9, 3, '2-1', '能力', '能够使用网络抓包工具分析协议报文格式，具备网络故障排查和中小规模组网设计的基本能力');
INSERT INTO `course_objective` VALUES (10, 4, '1-1', '知识', '理解计算机网络体系结构、OSI和TCP/IP参考模型，掌握物理层、数据链路层、网络层、传输层及应用层的核心协议原理');
INSERT INTO `course_objective` VALUES (11, 4, '2-1', '能力', '能够使用网络抓包工具分析协议报文格式，具备网络故障排查和中小规模组网设计的基本能力');
INSERT INTO `course_objective` VALUES (12, 4, '2-2', '能力', '能够根据实际应用需求进行IP地址规划与子网划分，完成基础网络设备（交换机、路由器）的配置与调试，具备构建和维护小型局域网络的能力。');
INSERT INTO `course_objective` VALUES (13, 1, '1-2', '知识', '掌握查找表（静态查找、动态查找）和哈希表的实现原理，理解不同查找算法（如二分查找、二叉排序树、平衡二叉树、B树）的效率差异及适用条件');
INSERT INTO `course_objective` VALUES (14, 1, '1-3', '能力', '能够运用排序与查找算法对大规模数据进行高效处理，掌握内排序（插入、交换、选择、归并、基数排序）及外排序的基本方法，并能针对数据特征优化算法性能');
INSERT INTO `course_objective` VALUES (15, 3, '1-2', '知识', '系统掌握计算机网络分层体系结构（OSI/RM及TCP/IP模型），理解各层主要协议（如HTTP、TCP、IP、以太网等）的工作原理、数据封装格式及典型交互过程。');
INSERT INTO `course_objective` VALUES (16, 3, '1-3', '知识', '理解分组交换、可靠传输、拥塞控制、路由算法、地址解析等网络核心技术与工作机制，掌握网络系统的主要性能指标（带宽、时延、吞吐量等）及其分析方法。');
INSERT INTO `course_objective` VALUES (17, 3, '2-2', '能力', '能够根据实际应用需求进行IP地址规划与子网划分，完成基础网络设备（交换机、路由器）的配置与调试，具备构建和维护小型局域网络的能力。');
INSERT INTO `course_objective` VALUES (18, 3, '2-3', '能力', '能够运用常用网络诊断工具（如Wireshark、Ping、Traceroute等）进行协议分析与网络故障排查，具备识别、定位和解决常见网络问题的实践能力。');
INSERT INTO `course_objective` VALUES (19, 3, '3-1', '价值', '理解网络安全对国家和社会的重要性，自觉遵守网络法律法规与职业道德，在学习和实践中养成安全、合规使用网络技术的责任意识。');
INSERT INTO `course_objective` VALUES (20, 3, '3-2', '价值', '在网络实验和项目实践中，培养团队协作精神和沟通能力，养成严谨求实的工程素养，理解网络技术对社会发展的促进作用，增强科技报国的使命感。');
INSERT INTO `course_objective` VALUES (21, 4, '1-2', '知识', '系统掌握计算机网络分层体系结构（OSI/RM及TCP/IP模型），理解各层主要协议（如HTTP、TCP、IP、以太网等）的工作原理、数据封装格式及典型交互过程。');
INSERT INTO `course_objective` VALUES (22, 4, '1-3', '知识', '理解分组交换、可靠传输、拥塞控制、路由算法、地址解析等网络核心技术与工作机制，掌握网络系统的主要性能指标（带宽、时延、吞吐量等）及其分析方法。');
INSERT INTO `course_objective` VALUES (23, 4, '2-3', '能力', '能够运用常用网络诊断工具（如Wireshark、Ping、Traceroute等）进行协议分析与网络故障排查，具备识别、定位和解决常见网络问题的实践能力。');
INSERT INTO `course_objective` VALUES (24, 4, '3-1', '价值', '理解网络安全对国家和社会的重要性，自觉遵守网络法律法规与职业道德，在学习和实践中养成安全、合规使用网络技术的责任意识。');
INSERT INTO `course_objective` VALUES (25, 4, '3-2', '价值', '在网络实验和项目实践中，培养团队协作精神和沟通能力，养成严谨求实的工程素养，理解网络技术对社会发展的促进作用，增强科技报国的使命感。');
INSERT INTO `course_objective` VALUES (26, 5, '1-1', '知识', '系统掌握数据库系统的基本概念、数据模型（层次、网状、关系模型）及数据库体系结构，深入理解关系代数和关系演算等关系数据理论。');
INSERT INTO `course_objective` VALUES (27, 5, '1-2', '知识', '掌握SQL语言的数据定义、数据操纵和数据控制功能，理解关系数据库设计的规范化理论（1NF至BCNF），掌握事务管理、并发控制与恢复技术的基本原理。');
INSERT INTO `course_objective` VALUES (28, 5, '1-3', '知识', '了解NoSQL数据库、分布式数据库及云数据库等新型数据库技术的发展趋势与应用场景。');
INSERT INTO `course_objective` VALUES (29, 5, '2-1', '能力', '能够针对实际应用需求进行数据库的规划与设计，运用ER图进行概念模型设计，并将ER模型转换为合理的关系模式，具备完成完整数据库设计方案的能力。');
INSERT INTO `course_objective` VALUES (30, 5, '2-2', '能力', '能够熟练运用SQL语言完成数据库的创建、查询、更新、视图定义、完整性约束设置及权限管理等操作，具备数据库应用系统开发的基本实践能力。');
INSERT INTO `course_objective` VALUES (31, 5, '2-3', '能力', '能够运用事务隔离级别和锁机制分析并解决并发操作中的数据一致性问题，具备基本的数据库性能调优与故障恢复能力。');
INSERT INTO `course_objective` VALUES (32, 5, '3-1', '价值', '树立数据安全与隐私保护意识，理解数据作为重要战略资源对国家和社会发展的意义，自觉遵守数据管理相关法律法规与职业道德规范。');
INSERT INTO `course_objective` VALUES (33, 5, '3-2', '价值', '养成严谨细致的工作作风和科学的数据管理思维，理解规范化的数据库设计对信息系统稳定运行的重要价值。');
INSERT INTO `course_objective` VALUES (34, 5, '3-3', '价值', '理解数据库技术在数字经济、智慧城市等国家战略中的支撑作用，增强以数据技术服务社会发展的责任感与使命感。');
INSERT INTO `course_objective` VALUES (35, 6, '1-1', '知识', '系统掌握力学（质点运动学与动力学、刚体转动）、电磁学（静电场、稳恒磁场、电磁感应）和热学（热力学定律）的基本概念、基本定律和核心物理模型。');
INSERT INTO `course_objective` VALUES (36, 6, '1-2', '知识', '理解波动光学（干涉、衍射、偏振）和近代物理（相对论基础、量子物理初步）的基本原理，掌握物理量的定义、物理意义及适用范围与条件。');
INSERT INTO `course_objective` VALUES (37, 6, '2-1', '能力', '能够运用微积分和矢量分析等数学工具，对典型物理问题（如变力做功、电场强度计算、感应电动势等）建立数学模型并进行定量求解，具备物理建模与数学推导能力。');
INSERT INTO `course_objective` VALUES (38, 6, '2-2', '能力', '能够通过物理实验对物理规律进行验证和测量，具备实验方案设计、实验数据采集与处理、误差分析和实验报告撰写的能力。');
INSERT INTO `course_objective` VALUES (39, 6, '3-1', '价值', '感悟自然科学中蕴含的辩证唯物主义世界观和方法论，理解物理规律的普遍性与客观性，培养尊重事实、尊重规律的求真精神。');
INSERT INTO `course_objective` VALUES (40, 6, '3-2', '价值', '理解物理学是工程技术的基础支撑，认识基础科学研究对国家科技自立自强的重要意义，激发科学探索兴趣和科技报国的志向。');
INSERT INTO `course_objective` VALUES (41, 6, '3-3', '价值', '通过物理发展史的学习，体会科学发现中的批判性思维和创新精神，培养不畏困难、勇于探索的科学品质。');
INSERT INTO `course_objective` VALUES (42, 7, '1-1', '知识', '系统掌握行列式、矩阵、向量组与线性方程组的基本概念、性质和运算规则，理解矩阵的秩、向量组的线性相关性与线性方程组解的结构理论。');
INSERT INTO `course_objective` VALUES (43, 7, '1-2', '知识', '掌握矩阵的特征值与特征向量、矩阵相似对角化及二次型标准化的理论与方法，理解正定矩阵等在实际问题中的应用背景。');
INSERT INTO `course_objective` VALUES (44, 7, '2-1', '能力', '能够运用矩阵运算和初等变换方法求解线性方程组，完成矩阵的秩的计算、向量组极大无关组的确定等操作，具备运用代数方法解决工程中线性问题的基本能力。');
INSERT INTO `course_objective` VALUES (45, 7, '2-2', '能力', '能够将实际问题（如图像处理、数据降维、网络分析等）中的数学关系抽象为线性代数模型，并运用特征分析、矩阵分解等方法进行求解与分析。');
INSERT INTO `course_objective` VALUES (46, 7, '3-1', '价值', '理解线性代数作为现代科学与工程技术的基础语言的重要地位，体会数学的简洁美与抽象美，培养严谨的逻辑思维能力。');
INSERT INTO `course_objective` VALUES (47, 7, '3-2', '价值', '认识线性代数在人工智能、数据分析、密码学等前沿领域的广泛应用，理解基础数学对国家科技创新和产业升级的支撑作用。');
INSERT INTO `course_objective` VALUES (48, 7, '3-3', '价值', '培养将复杂问题抽象化、结构化处理的思维方式，养成在学习中追求本质、把握规律的数学素养。');
INSERT INTO `course_objective` VALUES (49, 8, '1-1', '知识', '系统掌握一元函数微积分的核心理论，包括极限与连续、导数与微分、微分中值定理及其应用、不定积分与定积分的计算，理解积分上限函数的性质与微积分基本定理。');
INSERT INTO `course_objective` VALUES (50, 8, '1-2', '知识', '掌握多元函数微分学（偏导数、全微分、方向导数、多元极值）、重积分、曲线积分与曲面积分的基本概念与计算方法，理解格林公式、高斯公式和斯托克斯公式的基本思想与联系。');
INSERT INTO `course_objective` VALUES (51, 8, '1-3', '知识', '掌握常数项级数、幂级数的收敛性判别方法及函数展开为幂级数的条件与方法，了解傅里叶级数的基本概念与简单应用。');
INSERT INTO `course_objective` VALUES (52, 8, '2-1', '能力', '能够运用极限、导数、积分等基本工具对工程问题中的变量关系、变化率、累积量进行分析与计算，具备建立和求解微分方程模型以描述工程中动态过程的能力。');
INSERT INTO `course_objective` VALUES (53, 8, '2-2', '能力', '能够将工程中的几何、物理问题（如面积、体积、质量、质心、通量、环量等）抽象为定积分、重积分或曲线曲面积分的数学形式并进行准确计算，具备将实际问题转化为数学模型并求解的综合能力。');
INSERT INTO `course_objective` VALUES (54, 8, '2-3', '能力', '能够运用级数工具进行函数逼近与近似计算，具备用数学方法处理工程中复杂函数计算问题的初步能力。');
INSERT INTO `course_objective` VALUES (55, 8, '3-1', '价值', '感悟微积分所蕴含的“无限细分”与“无限求和”的辩证思想，理解运动变化与动态平衡的科学世界观，培养用变化的眼光分析问题的思维习惯。');
INSERT INTO `course_objective` VALUES (56, 8, '3-2', '价值', '理解高等数学是全部后续专业课程的核心基础，认识数学能力对计算机科学与技术专业人才专业发展高度的关键影响，树立夯实基础的自觉意识。');
INSERT INTO `course_objective` VALUES (57, 8, '3-3', '价值', '通过数学建模与科学计算的学习实践，培养严谨缜密的逻辑推理能力和求真务实的学习态度，体会基础学科在服务国家战略需求中的不可替代价值。');
INSERT INTO `course_objective` VALUES (58, 2, '1-1', '知识', '系统掌握C语言的基本语法规则和程序结构，包括基本数据类型（整型、实型、字符型）、运算符与表达式、常量与变量的定义及使用，理解C语言程序的编译、链接与执行过程。');
INSERT INTO `course_objective` VALUES (59, 2, '1-2', '知识', '掌握C语言的高级编程特性，包括数组（一维/二维数组及字符数组）、指针（指针与数组的关系、指针与函数、动态内存分配）、结构体与共用体的定义与使用，以及文件的基本操作（文件的打开/关闭、顺序/随机读写）。');
INSERT INTO `course_objective` VALUES (60, 2, '3-1', '价值', '理解C语言作为计算机专业核心基础语言的重要地位，认识扎实的编程基本功对后续操作系统、数据结构、嵌入式系统等专业课程学习的支撑作用，树立精益求精的专业态度。');
INSERT INTO `course_objective` VALUES (61, 2, '3-2', '价值', '体会底层编程技术在国家关键基础软件和自主可控信息系统建设中的战略价值，增强科技自立自强的使命感和责任感，理解程序设计中“内存管理”“边界检查”等技术细节对信息安全保障的重要意义。');
INSERT INTO `course_objective` VALUES (62, 9, '1-1', '知识', '测试');
INSERT INTO `course_objective` VALUES (63, 9, '2-1', '能力', '测试');
INSERT INTO `course_objective` VALUES (64, 9, '3-1', '价值', '测试');

-- ----------------------------
-- Table structure for course_outline
-- ----------------------------
DROP TABLE IF EXISTS `course_outline`;
CREATE TABLE `course_outline`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `class_id` bigint(0) NOT NULL COMMENT '所属教学班级 (一对一)',
  `status` enum('DRAFT','LOCKED') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'DRAFT' COMMENT '大纲状态',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_class`(`class_id`) USING BTREE,
  CONSTRAINT `fk_outline_class` FOREIGN KEY (`class_id`) REFERENCES `teaching_class` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '课程大纲' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of course_outline
-- ----------------------------
INSERT INTO `course_outline` VALUES (1, 1, 'DRAFT');
INSERT INTO `course_outline` VALUES (2, 2, 'DRAFT');
INSERT INTO `course_outline` VALUES (3, 3, 'DRAFT');
INSERT INTO `course_outline` VALUES (4, 4, 'DRAFT');
INSERT INTO `course_outline` VALUES (5, 5, 'DRAFT');
