-- ----------------------------
-- Table structure for grad_requirement
-- ----------------------------
DROP TABLE IF EXISTS `grad_requirement`;
CREATE TABLE `grad_requirement`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `major_id` bigint(0) NOT NULL COMMENT '所属专业',
  `req_no` int(0) NOT NULL COMMENT '编号 (1~8)',
  `title` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '要求标题',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '详细描述',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_major`(`major_id`) USING BTREE,
  CONSTRAINT `fk_grad_req_major` FOREIGN KEY (`major_id`) REFERENCES `sys_major` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 10 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '毕业要求' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of grad_requirement
-- ----------------------------
INSERT INTO `grad_requirement` VALUES (1, 1, 1, '工程知识', '遵守法律法规，具有人文底蕴和科学精神');
INSERT INTO `grad_requirement` VALUES (2, 1, 2, '问题分析', '具有从教意愿和积极从教的心理');
INSERT INTO `grad_requirement` VALUES (3, 1, 3, '设计/开发解决方案', '掌握所教学科的基本知识、基本原理和基本技能');
INSERT INTO `grad_requirement` VALUES (4, 1, 4, '研究', '在教育实践中能够进行教学设计、实施和评价');
INSERT INTO `grad_requirement` VALUES (5, 1, 5, '使用现代工具', '掌握班级组织与建设的工作规律和基本方法');
INSERT INTO `grad_requirement` VALUES (6, 1, 6, '工程与社会', '了解学科育人的理论与方法');
INSERT INTO `grad_requirement` VALUES (7, 1, 7, '环境与可持续发展', '具有终身学习与专业发展意识');
INSERT INTO `grad_requirement` VALUES (8, 1, 8, '职业规范', '理解学习共同体的作用，具有团队协作精神');

-- ----------------------------
-- Table structure for indicator
-- ----------------------------
DROP TABLE IF EXISTS `indicator`;
CREATE TABLE `indicator`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `grad_req_id` bigint(0) NOT NULL COMMENT '所属毕业要求',
  `indicator_no` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '编号, 如 3-1',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '指标点描述',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_grad_req`(`grad_req_id`) USING BTREE,
  CONSTRAINT `fk_indicator_grad_req` FOREIGN KEY (`grad_req_id`) REFERENCES `grad_requirement` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 37 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '毕业要求指标点' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of indicator
-- ----------------------------
INSERT INTO `indicator` VALUES (1, 3, '3-1', '掌握全流程设计方法：掌握计算机应用系统设计和产品开发全周期、全流程的方法与技术。\n');
INSERT INTO `indicator` VALUES (3, 3, '3-3', '满足特定需求的设计：能够针对特定需求，完成计算机软硬件系统或功能模块的设计，并在设计中体现创新意识。\n');
INSERT INTO `indicator` VALUES (4, 3, '3-4', '考虑现实约束因素：在设计环节中，能够综合考虑社会、健康、安全、法律、文化及环境等现实约束因素。\n');
INSERT INTO `indicator` VALUES (5, 4, '4-1', '调研与分析解决方案：能够基于科学原理并借助文献研究，调研和分析计算机复杂工程问题的解决方案。\n');
INSERT INTO `indicator` VALUES (6, 4, '4-2', '设计实验与安全实施：能够根据对象特征，选择研究路线并设计可行的实验方案，安全地开展实验并采集数据。\n');
INSERT INTO `indicator` VALUES (7, 4, '4-3', '分析与解释数据：能够对实验数据进行分析、解释和建模，通过信息综合得到合理有效的结论。\n');
INSERT INTO `indicator` VALUES (8, 7, '7-1', '理解可持续发展理念：知晓和理解环境保护和可持续发展的理念与内涵，了解国家相关政策法规。\n');
INSERT INTO `indicator` VALUES (18, 5, '5-1', '了解工具原理与局限：了解专业常用的信息技术工具、开发环境和模拟软件的原理，并理解其局限性。\n');
INSERT INTO `indicator` VALUES (19, 1, '1-1', '掌握数学与自然科学知识：能够系统掌握数学、物理等自然科学知识，并将其用于计算机领域复杂工程问题的恰当表述。\n');
INSERT INTO `indicator` VALUES (20, 1, '1-2', '建立与求解数学模型：能够针对计算机领域的特定对象，运用相关知识建立数学模型并进行分析求解。\n');
INSERT INTO `indicator` VALUES (21, 1, '1-3', '解决复杂工程问题：能够将工程基础、专业知识和数学模型方法，用于分析、推演和解决计算机领域复杂工程问题。\n');
INSERT INTO `indicator` VALUES (22, 2, '2-1', '识别与表达关键环节：能够应用数学、自然科学和工程科学的基本原理，识别和判断复杂工程问题的关键环节与影响因素。\n');
INSERT INTO `indicator` VALUES (23, 2, '2-2', '文献研究与寻求方案：能认识到解决问题有多种方案，通过文献研究寻求可替代的解决方案，并分析其可行性。\n');
INSERT INTO `indicator` VALUES (24, 2, '2-3', '获得有效结论：能够运用基本原理，借助文献研究，分析工程问题各环节的影响，并得出有效结论。\n');
INSERT INTO `indicator` VALUES (25, 5, '5-2', '选择与使用恰当工具：能够选择和使用恰当的现代工具，对复杂工程问题进行分析、计算与设计。\n');
INSERT INTO `indicator` VALUES (26, 5, '5-3', '开发与选用工具进行模拟：能够针对具体问题，开发或选用满足需求的现代工具，进行模拟与预测，并分析其局限性。\n');
INSERT INTO `indicator` VALUES (27, 6, '6-1', '理解社会制约因素：了解专业领域的技术标准、知识产权、产业政策和法律法规，理解不同社会文化对工程活动的影响。\n');
INSERT INTO `indicator` VALUES (28, 6, '6-2', '评价工程实践的影响：能够评价计算机工程实践及其解决方案对社会、健康、安全、法律及文化的影响，并理解应承担的责任。\n');
INSERT INTO `indicator` VALUES (29, 7, '7-2', '评价环境与社会影响：能够站在可持续发展角度，评价计算机工程实践对环境和社会可能造成的影响。\n');
INSERT INTO `indicator` VALUES (30, 8, '8-1', '具备人文与社会责任感：具有良好的人文社会科学素养、社会责任感，理解个人与社会的关系，树立正确的价值观。\n');
INSERT INTO `indicator` VALUES (31, 8, '8-2', '遵守职业道德与规范：理解并能在工程实践中自觉遵守工程职业道德和规范，履行工程师的职责。\n');
INSERT INTO `indicator` VALUES (32, 8, '8-3', '履行社会责任：理解工程师对公众安全、健康和福祉的社会责任，并在专业实践中自觉履行。\n');

-- ----------------------------
-- Table structure for macro_support_matrix
-- ----------------------------
DROP TABLE IF EXISTS `macro_support_matrix`;
CREATE TABLE `macro_support_matrix`  (
  `id` bigint(0) NOT NULL AUTO_INCREMENT,
  `course_id` bigint(0) NOT NULL COMMENT '课程',
  `indicator_id` bigint(0) NOT NULL COMMENT '指标点',
  `support_level` enum('H','M','L') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '支撑强度 (参考标记)',
  `weight` decimal(5, 4) NULL DEFAULT NULL COMMENT '总支撑权重 W_c',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_course_indicator`(`course_id`, `indicator_id`) USING BTREE,
  INDEX `idx_macro_matrix_indicator`(`indicator_id`) USING BTREE,
  CONSTRAINT `fk_macro_course` FOREIGN KEY (`course_id`) REFERENCES `course` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_macro_indicator` FOREIGN KEY (`indicator_id`) REFERENCES `indicator` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 295 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = '宏观支撑矩阵 (含权重W_c)' ROW_FORMAT = Dynamic;

